/* @lc app=leetcode id=2564 lang=kotlin */
class Solution { fun substringXorQueries(s: String, queries: Array<IntArray>): Array<IntArray> = s.indices.fold(mutableMapOf<Int, IntArray>()) { m, i -> m.apply { (0 until if (s[i] == '0') 1 else minOf(31, s.length - i)).fold(0) { acc, len -> (acc shl 1 or (s[i + len] - '0')).also { v -> if (v !in m) m[v] = intArrayOf(i, i + len) } } } }.let { m -> queries.map { q -> m[q[0] xor q[1]] ?: intArrayOf(-1, -1) }.toTypedArray() } }